import{_ as e,o as t,c as r,a4 as i}from"./chunks/framework.CzJ_HCFe.js";const m=JSON.parse('{"title":"Wedding (Vivaha) source profile","description":"","frontmatter":{},"headers":[],"relativePath":"reference/31-wedding-evidence-audit.md","filePath":"reference/31-wedding-evidence-audit.md","lastUpdated":1788720195000}'),d={name:"reference/31-wedding-evidence-audit.md"};function n(s,a,o,h,c,l){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="wedding-vivaha-source-profile" tabindex="-1">Wedding (Vivaha) source profile <a class="header-anchor" href="#wedding-vivaha-source-profile" aria-label="Permalink to &quot;Wedding (Vivaha) source profile&quot;">​</a></h1><h2 id="authority-and-status" tabindex="-1">Authority and status <a class="header-anchor" href="#authority-and-status" aria-label="Permalink to &quot;Authority and status&quot;">​</a></h2><p><code>wedding</code> follows B. V. Raman, <em>Muhurtha (Electional Astrology)</em>, Chapter IX, “Electing a Time for Marriage,” internal printed pages 41–42 (physical PDF pages 45–46 in the inspected 2020 Chistabo derivative). Raman is a modern secondary authority, not scripture. The claim <code>muhurta.wedding</code> means the configured criteria match this named passage; it does not claim that all regional Panchangams use the same method.</p><p>The former profile was contradicted: it rewarded the entire Purna family and penalized the entire Jaya family, reversing Raman on Pournami, Shukla Tritiya and Shukla Trayodashi. Those proxies have been removed.</p><h2 id="exact-automated-crosswalk" tabindex="-1">Exact automated crosswalk <a class="header-anchor" href="#exact-automated-crosswalk" aria-label="Permalink to &quot;Exact automated crosswalk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Criterion</th><th>Passage</th><th>Product treatment</th></tr></thead><tbody><tr><td>Lunar month</td><td>Magha, Phalguna, Vaishakha and Jyeshtha good; Kartika and Margashira ordinary</td><td>All six admitted</td></tr><tr><td>Conditional month</td><td>Pushya with Surya in Makara; Chaitra with Surya in Mesha</td><td>Exact <code>(Maasa, solar Rasi)</code> pairs admitted</td></tr><tr><td>Tithi</td><td>Reject Krishna Ekadashi through Amavasya, Rikta, Shashthi, Ashtami and Dwadashi; seven named Shukla Tithis best</td><td>Every non-rejected Shukla/Krishna Tithi admitted by exact Paksha-qualified name; no family proxy</td></tr><tr><td>Vara</td><td>Monday, Wednesday, Thursday and Friday best; Sunday/Saturday middling; Tuesday rejected</td><td>Six admitted, four receive a preference bonus</td></tr><tr><td>Nakshatra</td><td>Rohini, Mrigashira, Magha, Uttara, Hasta, Swati, Anuradha, Moola, Uttara Ashadha, Uttara Bhadrapada and Revati</td><td>Exact eleven-star gate; “Uttara” resolved as Uttara Phalguni</td></tr><tr><td>Yoga</td><td>Vyatipata, Dhruva, Mrityu, Ganda, Vajra, Shoola, Vishkambha, Atiganda, Vyaghata and Parigha rejected</td><td>Nine matching Nitya Yogas hard-gated; Mrityu remains manual because it is not one of the engine&#39;s 27 Nitya Yogas</td></tr><tr><td>Karana</td><td>Vishti rejected</td><td>Slot-level hard gate</td></tr><tr><td>Lagna</td><td>Mithuna, Kanya and Tula best; Vrishabha, Karka, Simha, Dhanu and Kumbha middling</td><td>Exact eight-Rasi gate with a bonus only for the best three</td></tr></tbody></table><p>The finder also retains separately sourced conservative samskara safeguards: Adhika and Pitru Paksha, Sankramana, Guru/Shukra combustion, Simha-Stha and the shared Visha/Dagdha layer. The Raman claim does not falsely attribute those extra filters to this passage.</p><h2 id="computed-and-mandatory-manual-prerequisites" tabindex="-1">Computed and mandatory manual prerequisites <a class="header-anchor" href="#computed-and-mandatory-manual-prerequisites" aria-label="Permalink to &quot;Computed and mandatory manual prerequisites&quot;">​</a></h2><p>Reject Magha and Moola Pada 1 and Revati Pada 4. Pada is not computed across every product surface, so these remain explicit mandatory checks. The same is true for Raman&#39;s named “Mrityu Yoga,” whose definition is not represented in the 27-Nitya-Yoga model.</p><p>The Drik browser chart post-screen rejects an occupied 7th, Mangala in the 8th, or Shukra in the 6th at any sampled state (the window edges and both sides of every known interior Drik Lagna transition). Malefics around Lagna, Chandra&#39;s association with another Graha, the named fortifications, compatibility, Tarabala, Chandrabala and Panchaka still require couple-specific review. Those unresolved facts cap every automated result below <code>Excellent</code>. Python/MCP retain the complete list as <code>manual_checks</code> because they do not call the chart service. See <a href="./54-muhurtam-election-chart-screening">Muhurtam election-chart screening</a>.</p><h2 id="published-practice-divergence" tabindex="-1">Published-practice divergence <a class="header-anchor" href="#published-practice-divergence" aria-label="Permalink to &quot;Published-practice divergence&quot;">​</a></h2><p>Drik Panchang&#39;s 2026 Hyderabad marriage table admits qualifying Tuesdays and Tithis including Chaturdashi, Pournami, Shashthi and Navami that this Raman method rejects. Drik Panchang also applies its own solar/lunar-month, Adhika, Chaturmas and Guru/Shukra Asta method.</p><p>This is recorded as <code>muhurta.wedding.drkpanchang_divergence</code>. The application does not present Raman-lineage results as identical to Drik Panchang&#39;s date set, and timing cannot replace consent or relationship judgment.</p>',13)])])}const p=e(d,[["render",n]]);export{m as __pageData,p as default};
